<template><section class="ped"><header class="head"><div><h1>{{edicion?'Editar pedido':'Registrar pedido'}}</h1><p class="muted">Solicitud de abastecimiento · No descuenta inventario al registrar.</p></div><RouterLink class="btn" to="/pedidos">← Volver al listado</RouterLink></header>
<form class="panel" @submit.prevent="guardar"><div v-if="error" class="error">{{error}}</div><div class="grid"><div><label>Ubicación solicitante *</label><select v-model="form.id_ubicacion_solicitante" required><option value="">Seleccione ubicación</option><option v-for="u in ubicaciones" :key="u.id_ubicacion" :value="u.id_ubicacion">{{u.nombre || u.nombre_ubicacion || `Ubicación #${u.id_ubicacion}`}}</option></select></div><div><label>Tipo de pedido *</label><input v-model.trim="form.tipo" maxlength="30" required placeholder="Ej.: ABASTECIMIENTO"></div><div><label>Fecha del pedido *</label><input v-model="form.fecha_pedido" type="datetime-local" required></div><div class="full"><label>Observación</label><textarea v-model="form.observacion" placeholder="Motivo o indicaciones del pedido"></textarea></div></div>
<h3>Detalle de presentaciones</h3><p class="muted">Cada presentación puede aparecer una sola vez. Indica paquetes, unidades o ambos.</p><div class="tablewrap"><table><thead><tr><th>Presentación *</th><th>Paquetes</th><th>Unidades</th><th>Acción</th></tr></thead><tbody><tr v-for="(d,i) in form.detalles" :key="i"><td><select v-model="d.id_presentacion" required><option value="">Seleccione presentación</option><option v-for="p in presentaciones" :key="p.id_presentacion" :value="p.id_presentacion">{{p.producto?.nombre || 'Producto'}} · {{p.nombre_presentacion}} · {{p.codigo_sku}}</option></select></td><td><input type="number" min="0" step="1" v-model.number="d.cantidad_paquetes" required></td><td><input type="number" min="0" step="1" v-model.number="d.cantidad_unidades" required></td><td><button type="button" class="btn danger small" :disabled="form.detalles.length===1" @click="form.detalles.splice(i,1)">Quitar</button></td></tr></tbody></table></div><div class="rowactions"><button type="button" class="btn" @click="agregar">+ Agregar presentación</button></div>
<div class="rowactions"><RouterLink to="/pedidos" class="btn">Cancelar</RouterLink><button class="btn primary" :disabled="guardando || cargando">{{guardando?'Guardando...':edicion?'Guardar cambios':'Registrar pedido'}}</button></div></form></section></template>
<script>
import api from '../../services/api';
const nuevaLinea=()=>({id_presentacion:'',cantidad_paquetes:0,cantidad_unidades:0});
export default {data(){return {form:{id_ubicacion_solicitante:'',tipo:'ABASTECIMIENTO',fecha_pedido:new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),observacion:'',detalles:[nuevaLinea()]},ubicaciones:[],presentaciones:[],error:'',guardando:false,cargando:true}},computed:{edicion(){return Boolean(this.$route.params.id)}},async mounted(){try{const [u,p]=await Promise.all([this.todos('/api/ubicaciones'),this.todos('/api/presentaciones')]);this.ubicaciones=u;this.presentaciones=p;if(this.edicion){const {data}=await api.get(`/api/pedidos/${this.$route.params.id}`);if(data.estado!=='PENDIENTE'){this.error='Este pedido ya no está pendiente y no puede editarse.';return}this.form={id_ubicacion_solicitante:data.id_ubicacion_solicitante,tipo:data.tipo,fecha_pedido:data.fecha_pedido?.slice(0,16)||'',observacion:data.observacion||'',detalles:data.detalles.map(d=>({id_presentacion:d.id_presentacion,cantidad_paquetes:d.cantidad_paquetes,cantidad_unidades:d.cantidad_unidades}))}}}catch(e){this.error=e.response?.data?.message||'Error al cargar ubicaciones o presentaciones. Verifica permisos y conexión.'}finally{this.cargando=false}},methods:{async todos(url){let all=[],page=1,last=1;do{const {data}=await api.get(url,{params:{page,limit:100}});const arr=Array.isArray(data)?data:(data.data||[]);all.push(...arr);last=Array.isArray(data)?1:(data.last_page||1);page++}while(page<=last&&page<=200);return all},agregar(){this.form.detalles.push(nuevaLinea())},async guardar(){this.error='';const ids=this.form.detalles.map(d=>String(d.id_presentacion));if(ids.some(x=>!x)){this.error='Selecciona una presentación en cada detalle.';return}if(new Set(ids).size!==ids.length){this.error='No se puede repetir la misma presentación en un pedido.';return}if(this.form.detalles.some(d=>!Number.isInteger(Number(d.cantidad_paquetes))||!Number.isInteger(Number(d.cantidad_unidades))||Number(d.cantidad_paquetes)<0||Number(d.cantidad_unidades)<0||(Number(d.cantidad_paquetes)===0&&Number(d.cantidad_unidades)===0))){this.error='Cada detalle debe tener al menos un paquete o una unidad y cantidades enteras no negativas.';return}this.guardando=true;try{const payload={...this.form,detalles:this.form.detalles.map(d=>({...d,id_presentacion:Number(d.id_presentacion),cantidad_paquetes:Number(d.cantidad_paquetes),cantidad_unidades:Number(d.cantidad_unidades)}))};if(this.edicion)await api.post(`/api/pedidos/${this.$route.params.id}`,payload);else await api.post('/api/pedidos',payload);this.$router.push('/pedidos')}catch(e){const errors=e.response?.data?.errors;this.error=(errors?Object.values(errors).flat().join(' · '):null)||e.response?.data?.message||'No se pudo guardar el pedido.'}finally{this.guardando=false}}}}
</script>
<style scoped>
.ped{padding:24px;max-width:1450px;margin:auto;color:#103a2d}.head{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-bottom:22px}.head h1{font-size:30px;margin:0;color:#0c3025}.muted{color:#61756c;font-size:14px}.panel{background:#fff;border:1px solid #dbe7df;border-radius:16px;padding:24px;box-shadow:0 8px 24px #103a2d0b;margin-bottom:18px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px}.toolbar>*{flex:1;min-width:150px}input,select,textarea{width:100%;min-height:42px;border:1px solid #cbded2;border-radius:9px;padding:10px;background:white;color:#183b2e;font:inherit}textarea{min-height:88px}label{font-size:13px;font-weight:700;display:block;margin-bottom:7px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.full{grid-column:1/-1}.btn{border:1px solid #cbded2;border-radius:9px;padding:11px 16px;cursor:pointer;background:#fff;color:#124734;font-weight:700}.btn:hover{filter:brightness(.96)}.primary{background:#f47b20;color:#fff;border-color:#f47b20}.danger{background:#fff0ee;color:#a72c2c;border-color:#f3cccc}.small{padding:7px 10px;font-size:12px}.btn:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;gap:8px;flex-wrap:wrap}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:14px}th{background:#0c3025;color:white;text-align:left;padding:13px}td{border-bottom:1px solid #e0e9e3;padding:12px;vertical-align:middle}.error{color:#a52d2d;background:#fff0ee;border-radius:8px;padding:12px;margin-bottom:15px}.pill{background:#eaf4ee;color:#0b5c3a;border-radius:20px;padding:5px 10px;font-weight:700;font-size:12px}.rowactions{display:flex;gap:10px;justify-content:flex-end;margin-top:20px}@media(max-width:720px){.grid{grid-template-columns:1fr}.ped{padding:12px}.panel{padding:15px}.head h1{font-size:24px}}
</style>